package main
import("bytes";"encoding/json";"fmt";"io";"net/http";"os";"strings";"time";"github.com/golang-jwt/jwt/v5";"gorm.io/driver/sqlite";"gorm.io/gorm";"webbuilder/internal/database/models")
func main(){db,e:=gorm.Open(sqlite.Open("../../../data/webbuilder.db"),&gorm.Config{});if e!=nil{panic(e)};var u models.User;db.First(&u);var p models.Project;db.Where("user_id = ?",u.ID).Order("id DESC").First(&p);sec,_:=os.ReadFile("../../../.jwt-secret");t:=jwt.NewWithClaims(jwt.SigningMethodHS256,jwt.MapClaims{"uid":u.ID,"exp":time.Now().Add(time.Hour).Unix()});tok,_:=t.SignedString([]byte(strings.TrimSpace(string(sec))));base:=fmt.Sprintf("http://127.0.0.1:18082/api/projects/%d/migrations",p.ID);call:=func(method,url string,body any){b,_:=json.Marshal(body);req,_:=http.NewRequest(method,url,bytes.NewReader(b));req.Header.Set("Authorization","Bearer "+tok);req.Header.Set("Content-Type","application/json");resp,e:=http.DefaultClient.Do(req);if e!=nil{fmt.Println("ERR",e);return};out,_:=io.ReadAll(resp.Body);resp.Body.Close();fmt.Printf("%s %d %s\n",method,resp.StatusCode,string(out))};call("POST",base,map[string]any{"name":"create_migration_test","upSql":"CREATE TABLE migration_test (id SERIAL PRIMARY KEY, name TEXT NOT NULL);","downSql":"DROP TABLE migration_test;"});call("GET",base,nil);var rows []models.ProjectMigration;db.Where("project_id = ?",p.ID).Order("id DESC").Find(&rows);if len(rows)>0{call("POST",fmt.Sprintf("%s/%d/rollback",base,rows[0].ID),map[string]any{})};call("POST",base,map[string]any{"name":"blocked_insert","upSql":"INSERT INTO migration_test (name) VALUES ('x');","downSql":""})}